#include <stdio.h>
#include <stdlib.h>

int main() {
    int n = 5;
    int *arr = malloc(n * sizeof(int));   // size for n ints, not just one
    if (arr == NULL) {
        printf("Allocation failed\n");
        return 1;
    }
    for (int i = 0; i < n; i++) arr[i] = i * i;

    int *bigger = realloc(arr, 10 * sizeof(int));   // temp pointer, checked before reassigning
    if (bigger == NULL) {
        free(arr);
        return 1;
    }
    arr = bigger;

    printf("%d\n", arr[4]);   // 16
    free(arr);                 // exactly one free() for this allocation
    arr = NULL;                // defensive: avoid an accidental dangling-pointer reuse
    return 0;
}
